/**
 * Parse a configuration value that is expected to be a positive integer.
 *
 * Accepts a raw string (as typically read from env vars or config files), `null`, or `undefined`.
 * Returns the parsed positive integer, or `null` when the value is missing, empty, explicitly
 * disabled (`'0'`, `'false'`, `'null'`, `'undefined'`), or otherwise not a positive integer.
 */
export const parsePositiveIntegerConfigValue = (
  value: string | null | undefined
): number | null => {
  if (value == null) {
    return null;
  }

  const trimmed = value.trim();

  if (trimmed === '') {
    return null;
  }

  if (['0', 'false', 'null', 'undefined'].includes(trimmed.toLowerCase())) {
    return null;
  }

  const parsed = Number(trimmed);

  if (!Number.isInteger(parsed) || parsed <= 0) {
    return null;
  }

  return parsed;
};

