    return null;
  }

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date;
};

/**
 * Parse a map of package versions to release timestamps.
 *
 * Returns a plain object mapping string keys to string values for valid objects (such as the
 * `time` field returned by the npm registry). Entries with empty string values are omitted.
 * Returns `null` for anything that is not a plain object (strings, arrays, `null`, `undefined`).
 */
export const parsePackageTimeMap = (value: unknown): Record<string, string> | null => {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return null;
  }

  const result: Record<string, string> = {};

  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === 'string' && entry !== '') {
      result[key] = entry;
    }
  }

  return result;
};

/** Compute the age, in whole minutes, of `publishedAt` relative to `referenceTime`. */
export const getAgeInMinutes = (referenceTime: Date, publishedAt: Date): number => {
  return Math.floor((referenceTime.getTime() - publishedAt.getTime()) / (1000 * 60));
};

/**
 * Find the latest stable version that is at least `minimumAgeGateInMinutes` old.
 *
 * Pre-release versions are skipped. Versions whose release time cannot be parsed are ignored.
 * Returns the highest matching stable version, or `null` if none qualifies.
 */
export const getLatestStableVersionAdheringToMinimumAgeGate = (
  versionToReleaseTime: Record<string, string>,
  minimumAgeGateInMinutes: number,
  referenceTime: Date = new Date()
): string | null => {
  const eligibleVersions = Object.entries(versionToReleaseTime)
    .filter(([version]) => valid(version) != null && prerelease(version) == null)
    .map(([version, time]) => ({ version, publishedAt: parseReleaseTime(time) }))
    .filter(
      (entry): entry is { version: string; publishedAt: Date } => entry.publishedAt !== null
    )
    .filter(
